def transform(grid):
    h, w = len(grid), len(grid[0])
    separator_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    separator_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    rbounds = [-1] + separator_rows + [h]
    cbounds = [-1] + separator_cols + [w]
    result = []
    for ra, rb in zip(rbounds, rbounds[1:]):
        if rb == ra + 1:
            continue
        line = []
        for ca, cb in zip(cbounds, cbounds[1:]):
            if cb == ca + 1:
                continue
            counts = {}
            for r in range(ra + 1, rb):
                for c in range(ca + 1, cb):
                    v = grid[r][c]
                    counts[v] = counts.get(v, 0) + 1
            # Each panel's dominant color is the empty/background output, unless
            # there are exactly two anomalous cells, which map to marker 1.
            background = max(counts, key=counts.get)
            marks = sum(n for color, n in counts.items() if color != background)
            line.append(1 if marks == 2 else background)
        result.append(line)
    return result", "exit_code": 0, "error": null}
